//! Which language the interface uses: the system's, or one of the bundled
//! translations.
//!
//! `BundledLanguage` (with `ALL`, `code`, `native_name` and `from_code`) is
//! generated by `build.rs` from the folders in `i18n/`, so a new translation
//! becomes a new variant. Settings store `"system"` or a locale code.
use serde::{Deserialize, Deserializer, Serialize, Serializer, de::Error as _};
use slint::{ModelRc, SharedString, VecModel};

use crate::i18n::ctr;

include!(concat!(env!("OUT_DIR"), "/language_table.rs"));

/// The chosen language. The language dropdown lists System first, then
/// `BundledLanguage::ALL` in order.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) enum LanguagePreference {
    #[default]
    System,
    Bundled(BundledLanguage),
}

impl LanguagePreference {
    pub(crate) fn is_system(&self) -> bool {
        *self == Self::System
    }

    /// The preference at a dropdown row; rows off the list mean System.
    pub(crate) fn from_combo_index(index: i32) -> Self {
        usize::try_from(index - 1)
            .ok()
            .and_then(|at| BundledLanguage::ALL.get(at))
            .map_or(Self::System, |language| Self::Bundled(*language))
    }

    pub(crate) fn combo_index(self) -> i32 {
        match self {
            Self::System => 0,
            Self::Bundled(language) => BundledLanguage::ALL
                .iter()
                .position(|l| *l == language)
                .map_or(0, |at| at as i32 + 1),
        }
    }

    /// The dropdown's rows. Built again after each switch so "System" is
    /// shown in the new language.
    pub(crate) fn menu_rows() -> ModelRc<SharedString> {
        let rows: Vec<SharedString> = std::iter::once(ctr!("AppearancePage", "System"))
            .chain(BundledLanguage::ALL.iter().map(|l| l.native_name().into()))
            .collect();
        ModelRc::new(VecModel::from(rows))
    }

    /// Switches the running interface. System uses the OS locale, or its
    /// base language (`es` for `es-ES`) when only that is bundled, and the
    /// source language (English) when neither is. Slint needs a component to
    /// exist before translations can be selected.
    pub(crate) fn apply(self) {
        let system;
        let locale = match self {
            Self::Bundled(language) => language.code(),
            Self::System => {
                system = sys_locale::get_locale().unwrap_or_default();
                system.as_str()
            }
        };
        let chosen = [locale, language_part(locale)]
            .into_iter()
            .any(|code| slint::select_bundled_translation(code).is_ok());
        if !chosen {
            let _ = slint::select_bundled_translation("");
        }
    }
}

impl Serialize for LanguagePreference {
    fn serialize<S: Serializer>(&self, out: S) -> Result<S::Ok, S::Error> {
        out.serialize_str(match self {
            Self::System => "system",
            Self::Bundled(language) => language.code(),
        })
    }
}

impl<'de> Deserialize<'de> for LanguagePreference {
    /// An unknown code is an error, not System: a mistyped setting should
    /// be noticed (the settings loader reports it and uses defaults).
    fn deserialize<D: Deserializer<'de>>(input: D) -> Result<Self, D::Error> {
        let code = String::deserialize(input)?;
        if code == "system" {
            return Ok(Self::System);
        }
        BundledLanguage::from_code(&code)
            .map(Self::Bundled)
            .ok_or_else(|| D::Error::custom(format!("unknown language code: {code:?}")))
    }
}

/// `es` from `es-ES`, `pt` from `pt_BR`, `en` from `en@latin`.
fn language_part(locale: &str) -> &str {
    locale.split(['-', '_', '@']).next().unwrap_or(locale)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bundled(code: &str) -> LanguagePreference {
        LanguagePreference::Bundled(BundledLanguage::from_code(code).unwrap())
    }

    #[test]
    fn system_is_the_first_row_and_every_language_follows_in_order() {
        assert_eq!(LanguagePreference::System.combo_index(), 0);
        for (at, language) in BundledLanguage::ALL.iter().enumerate() {
            let preference = LanguagePreference::Bundled(*language);
            assert_eq!(preference.combo_index(), at as i32 + 1);
            assert_eq!(LanguagePreference::from_combo_index(at as i32 + 1), preference);
        }
        let past = BundledLanguage::ALL.len() as i32 + 1;
        for row in [-1, 0, past, 9999] {
            assert!(LanguagePreference::from_combo_index(row).is_system(), "{row}");
        }
    }

    #[test]
    fn english_can_be_chosen_though_it_is_the_source_language() {
        let en = BundledLanguage::from_code("en").unwrap();
        assert_eq!(en.native_name(), "English");
        assert!(!bundled("en").is_system());
        assert!(BundledLanguage::from_code("xx").is_none());
    }

    #[test]
    fn settings_store_the_code_or_system() {
        #[derive(Serialize, Deserialize, PartialEq, Debug)]
        struct Settings {
            language: LanguagePreference,
        }
        for (preference, text) in [
            (bundled("es"), "language = \"es\"\n"),
            (LanguagePreference::System, "language = \"system\"\n"),
        ] {
            let settings = Settings { language: preference };
            assert_eq!(toml::to_string(&settings).unwrap(), text);
            assert_eq!(toml::from_str::<Settings>(text).unwrap(), settings);
        }
        assert!(toml::from_str::<Settings>("language = \"xx\"").is_err());
    }

    #[test]
    fn the_base_language_drops_region_and_variant() {
        for (locale, base) in [("es-ES", "es"), ("pt_BR", "pt"), ("en@latin", "en"), ("de", "de"), ("", "")] {
            assert_eq!(language_part(locale), base);
        }
    }
}
